#!/usr/bin/env python3
"""Load data from phpMyAdmin MariaDB/MySQL dump into PostgreSQL schema generated by convert.py.

Usage:
    load_data.py DUMP.sql SCHEMA_REPORT.json > data_load.sql
"""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path


def scan_quoted(s: str, i: int) -> int:
    i += 1
    while i < len(s):
        ch = s[i]
        if ch == "\\":
            i += 2
            continue
        if ch == "'":
            if i + 1 < len(s) and s[i + 1] == "'":
                i += 2
                continue
            return i + 1
        i += 1
    raise ValueError("unterminated string")


def unquote_mysql(lit: str) -> str:
    body = lit[1:-1]
    out, i = [], 0
    esc = {"n": "\n", "r": "\r", "t": "\t", "0": "", "b": "\b", "Z": "\x1a"}
    while i < len(body):
        ch = body[i]
        if ch == "\\" and i + 1 < len(body):
            nxt = body[i + 1]
            out.append(esc.get(nxt, nxt))
            i += 2
        elif ch == "'" and i + 1 < len(body) and body[i + 1] == "'":
            out.append("'")
            i += 2
        else:
            out.append(ch)
            i += 1
    return "".join(out)


def split_top_level(s: str, sep: str = ",") -> list[str]:
    parts, depth, cur, i = [], 0, [], 0
    while i < len(s):
        ch = s[i]
        if ch == "'":
            j = scan_quoted(s, i)
            cur.append(s[i:j])
            i = j
            continue
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        if ch == sep and depth == 0:
            parts.append("".join(cur).strip())
            cur = []
        else:
            cur.append(ch)
        i += 1
    if "".join(cur).strip():
        parts.append("".join(cur).strip())
    return parts


RESERVED = {
    "all", "analyse", "analyze", "and", "any", "array", "as", "asc", "asymmetric", "both", "case",
    "cast", "check", "collate", "column", "constraint", "create", "current_catalog", "current_date",
    "current_role", "current_time", "current_timestamp", "current_user", "default", "deferrable",
    "desc", "distinct", "do", "else", "end", "except", "false", "fetch", "for", "foreign", "from",
    "grant", "group", "having", "in", "initially", "intersect", "into", "lateral", "leading",
    "limit", "localtime", "localtimestamp", "not", "null", "offset", "on", "only", "or", "order",
    "placing", "primary", "references", "returning", "select", "session_user", "some", "symmetric",
    "table", "then", "to", "trailing", "true", "union", "unique", "user", "using", "variadic",
    "when", "where", "window", "with",
}


def q(ident: str) -> str:
    return f'"{ident}"' if ident in RESERVED or not re.fullmatch(r"[a-z_][a-z0-9_]*", ident) else ident


def main() -> None:
    dump_path = Path(sys.argv[1])
    report_path = Path(sys.argv[2])
    report = json.loads(report_path.read_text(encoding="utf-8"))
    bool_cols = set(report.get("booleans", []))

    text = dump_path.read_text(encoding="utf-8", errors="ignore")

    out: list[str] = [
        "-- GENERATED data load from MariaDB dump",
        "BEGIN;",
        "SET session_replication_role = 'replica';",
    ]

    for m in re.finditer(r"INSERT INTO `([^`]+)` \(([^)]+)\) VALUES\n(.*?);\n", text, re.S):
        table = m.group(1)
        raw_cols = [c.strip().strip("`") for c in m.group(2).split(",")]
        pg_cols = ["org_id" if c == "org_id_fk" else c for c in raw_cols]
        values_blob = m.group(3)

        rows_raw = split_top_level(values_blob, ",")
        pg_rows: list[str] = []
        for r in rows_raw:
            r = r.strip()
            if r.startswith("(") and r.endswith(")"):
                r = r[1:-1]
            vals = split_top_level(r, ",")
            pg_vals: list[str] = []
            for idx, v in enumerate(vals):
                col_key = f"{table}.{raw_cols[idx]}"
                v_str = v.strip()
                if v_str.upper() == "NULL":
                    pg_vals.append("NULL")
                elif col_key in bool_cols:
                    pg_vals.append("TRUE" if v_str.strip("'") in ("1", "true", "TRUE") else "FALSE")
                elif v_str.startswith("'"):
                    unq = unquote_mysql(v_str)
                    if unq in ("0000-00-00", "0000-00-00 00:00:00"):
                        pg_vals.append("NULL")
                    else:
                        pg_vals.append("'" + unq.replace("'", "''") + "'")
                else:
                    pg_vals.append(v_str)
            pg_rows.append("(" + ", ".join(pg_vals) + ")")

        col_list = ", ".join(q(c) for c in pg_cols)
        out.append(f"INSERT INTO {q(table)} ({col_list}) OVERRIDING SYSTEM VALUE VALUES\n" + ",\n".join(pg_rows) + ";")

    # Reset identity sequences
    out.append("""
DO $$
DECLARE
    rec RECORD;
    max_id BIGINT;
BEGIN
    FOR rec IN
        SELECT table_name, column_name
        FROM information_schema.columns
        WHERE table_schema = 'public' AND is_identity = 'YES'
    LOOP
        EXECUTE format('SELECT COALESCE(MAX(%I), 0) FROM %I', rec.column_name, rec.table_name) INTO max_id;
        IF max_id > 0 THEN
            EXECUTE format('ALTER TABLE %I ALTER COLUMN %I RESTART WITH %s', rec.table_name, rec.column_name, max_id + 1);
        END IF;
    END LOOP;
END $$;
""")
    out.append("SET session_replication_role = 'origin';")
    out.append("COMMIT;")
    print("\n".join(out))


if __name__ == "__main__":
    main()
